"""Contract tests for the content-pillar-atomizer skill file.

This snapshot ships a single artifact: the SKILL.md spec. There is no
application code to exercise, so the bounded, verifiable change is a
structural contract test that pins the skill file's frontmatter and the
section headings its own body promises. If the spec is edited in a way
that drops a required field or documented section, these tests fail.

Frontmatter is parsed by hand (no PyYAML dependency in this environment).
"""

from pathlib import Path

SKILL_PATH = Path(__file__).parent / "skills" / "content" / "content-pillar-atomizer" / "SKILL.md"


def _read_skill():
    assert SKILL_PATH.is_file(), f"missing skill file: {SKILL_PATH}"
    return SKILL_PATH.read_text(encoding="utf-8")


def _split_frontmatter(text):
    """Return (frontmatter_lines, body) for a `---`-delimited YAML header."""
    lines = text.splitlines()
    assert lines and lines[0].strip() == "---", "SKILL.md must open with a '---' frontmatter fence"
    for i in range(1, len(lines)):
        if lines[i].strip() == "---":
            return lines[1:i], "\n".join(lines[i + 1:])
    raise AssertionError("frontmatter is not closed with a second '---' fence")


def _top_level_keys(fm_lines):
    """Top-level `key:` names in the frontmatter (indented lines are nested)."""
    keys = []
    for line in fm_lines:
        if not line or line[0] in " \t#":
            continue
        if ":" in line:
            keys.append(line.split(":", 1)[0].strip())
    return keys


def test_frontmatter_has_required_keys():
    fm_lines, _ = _split_frontmatter(_read_skill())
    keys = _top_level_keys(fm_lines)
    for required in ("name", "description", "license", "metadata"):
        assert required in keys, f"frontmatter missing required key: {required!r}"


def test_skill_name_matches_directory():
    fm_lines, _ = _split_frontmatter(_read_skill())
    name_line = next(l for l in fm_lines if l.startswith("name:"))
    name = name_line.split(":", 1)[1].strip()
    assert name == "content-pillar-atomizer"
    assert SKILL_PATH.parent.name == name, "skill `name` must match its directory"


def test_metadata_block_is_complete():
    fm_lines, _ = _split_frontmatter(_read_skill())
    joined = "\n".join(fm_lines)
    for field in ("author:", "version:", "stage:"):
        assert field in joined, f"metadata block missing {field!r}"


def test_documented_sections_present():
    _, body = _split_frontmatter(_read_skill())
    headings = {line.strip() for line in body.splitlines() if line.startswith("## ")}
    expected = {
        "## Stage",
        "## When to Use",
        "## Input Schema",
        "## Workflow",
        "## Output Schema",
        "## Error Handling",
        "## References",
    }
    missing = expected - headings
    assert not missing, f"SKILL.md missing documented sections: {sorted(missing)}"


def test_title_heading_present():
    _, body = _split_frontmatter(_read_skill())
    assert "# Content Pillar Atomizer" in body.splitlines(), "missing top-level title heading"
